// Generates src/api/routes.ts from the node's route table (crates/musubi-server/src/openapi.rs, openapi::ROUTES),
// which the node's own tests keep equal to the axum router. Run by `npm run build`; do not edit routes.ts by hand.
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, resolve } from 'node:path'
const here = dirname(fileURLToPath(import.meta.url))
const src = resolve(here, '../../crates/musubi-server/src/openapi.rs')
const out = resolve(here, '../src/api/routes.ts')
if (!existsSync(src)) { console.error('gen-routes: ' + src + ' not found'); process.exit(1) }
const rs = readFileSync(src, 'utf8')
const table = rs.slice(rs.indexOf('pub const ROUTES'), rs.indexOf('];', rs.indexOf('pub const ROUTES')))
const rows = [...table.matchAll(/\(\s*"([A-Z]+)",\s*"([^"]+)",\s*"([^"]+)",?\s*\)/g)].map((m) => [m[1], m[2], m[3]])
if (rows.length < 100) { console.error('gen-routes: parsed only ' + rows.length + ' routes'); process.exit(1) }
const body = `// GENERATED by scripts/gen-routes.mjs from crates/musubi-server/src/openapi.rs — do not edit.
// [method, path, tag]; path params are written {name} exactly as the node registers them.
export const ROUTES = [
${rows.map(([m, p, t]) => `  ['${m}', '${p}', '${t}'],`).join('\n')}
] as const
export type ApiMethod = (typeof ROUTES)[number][0]
export type ApiPath = (typeof ROUTES)[number][1]
`
const prev = existsSync(out) ? readFileSync(out, 'utf8') : ''
if (prev !== body) writeFileSync(out, body)
console.log(`gen-routes: ${rows.length} routes${prev !== body ? ' (updated)' : ''}`)
